{
  "items": [
    {
      "name": "Finsupp.sum_eq_one_iff",
      "type": " {α : Type u_1} (d : α →₀ ℕ) : (d.sum fun x n => n) = 1 ↔ ∃ a, d = fun₀ | a => 1",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_single_index",
      "type": " {α : Type u_1} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] {a : α} {b : M} {h : α → M → N} (h_zero : h a 0 = 0) : (fun₀ | a => b).sum h = h a b",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_single",
      "type": " {α : Type u_1} {M : Type u_8} [AddCommMonoid M] (f : α →₀ M) : f.sum Finsupp.single = f",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.single_sum",
      "type": " {α : Type u_1} {ι : Type u_2} {M : Type u_8} {N : Type u_10} [Zero M] [AddCommMonoid N] (s : ι →₀ M) (f : ι → M → N) (a : α) : (fun₀ | a => s.sum f) = s.sum fun d c => fun₀ | a => f d c",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.sum_single_add_single",
      "type": " {ι : Type u_2} {A : Type u_4} {B : Type u_5} [AddCommMonoid A] [AddCommMonoid B] (f₁ f₂ : ι) (g₁ g₂ : A) (F : ι → A → B) (H : f₁ ≠ f₂) (HF : ∀ (f : ι), F f 0 = 0) : ((fun₀ | f₁ => g₁) + fun₀ | f₂ => g₂).sum F = F f₁ g₁ + F f₂ g₂",
      "module": "Mathlib.Algebra.BigOperators.Finsupp.Basic"
    },
    {
      "name": "Finsupp.mapDomain_apply",
      "type": " {α : Type u_1} {β : Type u_2} {M : Type u_5} [AddCommMonoid M] (f : α → β) (x : α →₀ M) (b : β) : (Finsupp.mapDomain f x) b = x.sum fun a m => (fun₀ | f a => m) b",
      "module": "Mathlib.Data.Finsupp.Basic"
    },
    {
      "name": "TensorProduct.finsuppScalarLeft_apply_tmul",
      "type": " {R : Type u_1} [CommSemiring R] {N : Type u_4} [AddCommMonoid N] [Module R N] {ι : Type u_5} [DecidableEq ι] (p : ι →₀ R) (n : N) : (TensorProduct.finsuppScalarLeft R N ι) (p ⊗ₜ[R] n) = p.sum fun i m => fun₀ | i => m • n",
      "module": "Mathlib.LinearAlgebra.DirectSum.Finsupp"
    },
    {
      "name": "TensorProduct.finsuppScalarRight_apply_tmul",
      "type": " {R : Type u_1} {S : Type u_2} [CommSemiring R] [Semiring S] [Algebra R S] {M : Type u_3} [AddCommMonoid M] [Module R M] [Module S M] [IsScalarTower R S M] {ι : Type u_5} [DecidableEq ι] (m : M) (p : ι →₀ R) : (TensorProduct.finsuppScalarRight R S M ι) (m ⊗ₜ[R] p) = p.sum fun i n => fun₀ | i => n • m",
      "module": "Mathlib.LinearAlgebra.DirectSum.Finsupp"
    },
    {
      "name": "TensorProduct.finsuppRight_apply_tmul",
      "type": " {R : Type u_1} {S : Type u_2} [CommSemiring R] [Semiring S] [Algebra R S] {M : Type u_3} [AddCommMonoid M] [Module R M] [Module S M] [IsScalarTower R S M] {N : Type u_4} [AddCommMonoid N] [Module R N] {ι : Type u_5} [DecidableEq ι] (m : M) (p : ι →₀ N) : (TensorProduct.finsuppRight R S M N ι) (m ⊗ₜ[R] p) = p.sum fun i n => fun₀ | i => m ⊗ₜ[R] n",
      "module": "Mathlib.LinearAlgebra.DirectSum.Finsupp"
    },
    {
      "name": "TensorProduct.finsuppLeft_apply_tmul",
      "type": " {R : Type u_1} {S : Type u_2} [CommSemiring R] [Semiring S] [Algebra R S] {M : Type u_3} [AddCommMonoid M] [Module R M] [Module S M] [IsScalarTower R S M] {N : Type u_4} [AddCommMonoid N] [Module R N] {ι : Type u_5} [DecidableEq ι] (p : ι →₀ M) (n : N) : (TensorProduct.finsuppLeft R S M N ι) (p ⊗ₜ[R] n) = p.sum fun i m => fun₀ | i => m ⊗ₜ[R] n",
      "module": "Mathlib.LinearAlgebra.DirectSum.Finsupp"
    },
    {
      "name": "Finsupp.single_le_sum",
      "type": " {α : Type u_6} {M : Type u_7} {N : Type u_8} [Zero M] [AddCommMonoid N] [PartialOrder N] [IsOrderedAddMonoid N] (f : α →₀ M) {g : α → M → N} (h : 0 ≤ fun x1 x2 => g x1 x2) (a : α) : (fun₀ | a => f a).sum g ≤ f.sum g",
      "module": "Mathlib.Data.Finsupp.Order"
    },
    {
      "name": "MvPolynomial.mkDerivationₗ_monomial",
      "type": " {σ : Type u_1} {R : Type u_2} {A : Type u_3} [CommSemiring R] [AddCommMonoid A] [Module R A] [Module (MvPolynomial σ R) A] (f : σ → A) (s : σ →₀ ℕ) (r : R) : (MvPolynomial.mkDerivationₗ R f) ((MvPolynomial.monomial s) r) = r • s.sum fun i k => (MvPolynomial.monomial (s - fun₀ | i => 1)) ↑k • f i",
      "module": "Mathlib.Algebra.MvPolynomial.Derivation"
    }
  ]
}
